// src/protocols/nontransferable/NonTransferableERC721.sol

/// @title NonTransferableERC721 — Non-transferable NFT base
/// @notice Abstract contract that makes any ERC-721 non-transferable.
/// Tokens can be minted and burned but never transferred between accounts.
abstract contract NonTransferableERC721 is ERC721 {
    error TransferNotAllowed();

    constructor(
        string memory name_,
        string memory symbol_
    ) ERC721(name_, symbol_) {}

    /// @dev Override _update to block transfers. Allow mint (from==0) and burn (to==0).
    function _update(
        address to,
        uint256 tokenId,
        address auth
    ) internal virtual override returns (address) {
        address from = _ownerOf(tokenId);

        if (from != address(0) && to != address(0)) {
            revert TransferNotAllowed();
        }

        return super._update(to, tokenId, auth);
    }
}

// src/protocols/poap/AttendancePOAP.sol

/// @title AttendancePOAP — Proof of Attendance NFT with peer verification
/// @notice Global soulbound ERC-721 POAP collection. Two instances per festival
/// deployment: one for festival-level POAPs, one for sub-event-level POAPs.
contract AttendancePOAP is NonTransferableERC721, IAttendancePOAP {
    address public factory;
    uint256 private _nextTokenId = 1; // Token ID 0 reserved as no-token sentinel

    mapping(address => bool) public isAuthorizedMinter;
    mapping(uint256 => POAPData) public poapData;

    // Peer verification state
    mapping(uint256 => uint256) public verificationCount;
    mapping(uint256 => mapping(uint256 => bool)) private _hasVerified;
    mapping(address => uint256) public verificationDeadline; // per source contract
    mapping(address => uint256[]) private _sourceToTokenIds; // reverse index

    modifier onlyFactory() {
        if (msg.sender != factory) revert OnlyFactory();
        _;
    }

    modifier onlyAuthorizedMinter() {
        if (!isAuthorizedMinter[msg.sender]) revert OnlyAuthorizedMinter();
        _;
    }

    constructor(address _factory) NonTransferableERC721("Conference POAP", "POAP") {
        factory = _factory;
    }

    // ── Factory Management ──

    /// @notice Transfer factory rights to a new address (e.g., from deployer EOA to Festival contract)
    function transferFactory(address newFactory) external onlyFactory {
        address previous = factory;
        factory = newFactory;
        emit FactoryTransferred(previous, newFactory);
    }

    /// @notice Permanently renounce factory rights. No further minter management possible.
    function renounceFactory() external onlyFactory {
        address previous = factory;
        factory = address(0);
        emit FactoryRenounced(previous);
    }

    // ── Minter Management ──

    function authorizeMinter(address minter) external onlyFactory {
        if (isAuthorizedMinter[minter]) revert AlreadyAuthorized();
        isAuthorizedMinter[minter] = true;
        emit MinterAuthorized(minter);
    }

    function revokeMinter(address minter) external onlyFactory {
        if (!isAuthorizedMinter[minter]) revert NotAuthorized();
        isAuthorizedMinter[minter] = false;
        emit MinterRevoked(minter);
    }

    // ── Minting ──

    function mintPOAP(
        address attendee,
        address sourceContract
    ) external onlyAuthorizedMinter returns (uint256 tokenId) {
        tokenId = _nextTokenId++;
        _safeMint(attendee, tokenId);

        poapData[tokenId] = POAPData({
            sourceContract: sourceContract,
            attendee: attendee,
            issuedAt: uint64(block.timestamp)
        });

        _sourceToTokenIds[sourceContract].push(tokenId);

        emit POAPMinted(tokenId, attendee, sourceContract);
    }

    // ── Peer Verification ──

    /// @notice Verify another attendee from the same source event.
    /// Both tokens must be from the same sourceContract. Cannot self-verify.
    function verify(uint256 callerTokenId, uint256 targetTokenId) external {
        if (callerTokenId == targetTokenId) revert SameToken();

        POAPData memory callerData = poapData[callerTokenId];
        POAPData memory targetData = poapData[targetTokenId];

        if (callerData.sourceContract != targetData.sourceContract) revert DifferentSourceContract();
        if (ownerOf(callerTokenId) != msg.sender) revert NotAuthorized();
        if (callerData.attendee == targetData.attendee) revert SelfVerification();

        // Check deadline if set (0 = no deadline = open indefinitely)
        uint256 deadline = verificationDeadline[callerData.sourceContract];
        if (deadline != 0 && block.timestamp > deadline) revert VerificationWindowClosed();

        if (_hasVerified[callerTokenId][targetTokenId]) revert AlreadyVerified();

        _hasVerified[callerTokenId][targetTokenId] = true;
        verificationCount[targetTokenId]++;

        emit PeerVerified(
            callerData.sourceContract,
            callerData.attendee,
            targetData.attendee,
            callerTokenId,
            targetTokenId
        );
    }

    /// @notice Set a verification deadline for a source contract.
    /// Only callable by authorized minters (the event contract itself).
    /// Once set, cannot be changed.
    function setVerificationDeadline(uint256 deadline) external onlyAuthorizedMinter {
        if (verificationDeadline[msg.sender] != 0) revert DeadlineAlreadySet();
        if (deadline <= block.timestamp) revert DeadlineInPast();

        verificationDeadline[msg.sender] = deadline;
        emit VerificationDeadlineSet(msg.sender, deadline);
    }

    // ── Views ──

    function getPOAPData(uint256 tokenId) external view returns (POAPData memory) {
        _requireOwned(tokenId);
        return poapData[tokenId];
    }

    function getVerificationCount(uint256 tokenId) external view returns (uint256) {
        return verificationCount[tokenId];
    }

    function getHasVerified(uint256 verifierTokenId, uint256 targetTokenId) external view returns (bool) {
        return _hasVerified[verifierTokenId][targetTokenId];
    }

    function getVerificationDeadline(address sourceContract) external view returns (uint256) {
        return verificationDeadline[sourceContract];
    }

    function getTokensBySource(address sourceContract) external view returns (uint256[] memory) {
        return _sourceToTokenIds[sourceContract];
    }
}

